import asyncio
from collections.abc import Awaitable, Callable

async def run_tasks(tasks: list[Callable[[], Awaitable[None]]], max_concurrent: int) -> None:
    if max_concurrent <= 0:
        raise ValueError("max_concurrent must be a positive integer")

    task_iter = iter(tasks)
    semaphore = asyncio.Semaphore(max_concurrent)
    running: set[asyncio.Task[None]] = set()

    async def worker(task: Callable[[], Awaitable[None]]) -> None:
        async with semaphore:
            await task()

    def start_one() -> bool:
        try:
            task = next(task_iter)
        except StopIteration:
            return False
        running.add(asyncio.create_task(worker(task)))
        return True

    async def cancel_running() -> None:
        for fut in running:
            if not fut.done():
                fut.cancel()
        if running:
            await asyncio.gather(*running, return_exceptions=True)

    try:
        # Start the first batch.
        for _ in range(max_concurrent):
            if not start_one():
                break

        while running:
            done, pending = await asyncio.wait(
                running, return_when=asyncio.FIRST_COMPLETED
            )
            running = pending
            for fut in done:
                if fut.cancelled():
                    continue
                exc = fut.exception()
                if exc is not None:
                    await cancel_running()
                    raise exc

            # Refill the running set up to max_concurrent.
            while len(running) < max_concurrent:
                if not start_one():
                    break
    except asyncio.CancelledError:
        await cancel_running()
        raise
